"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"culture":"destination","expedition":"primary"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Mindo cloud forest","si_tag":"expedition","tier":"essential","source":"https://destinationlesstravel.com/day-trips-from-quito/","timing":"[''Jun'', ''Jul'', ''Aug'', ''Sep'', ''Dec'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"2 hrs NW; 500+ birds, canopy ziplines, waterfalls, tubing, and bean-to-bar chocolate","si":"expedition","blurb":"2 hrs NW; 500+ birds, canopy ziplines, waterfalls, tubing, and bean-to-bar chocolate","when":"[''Jun'', ''Jul'', ''Aug'', ''Sep'', ''Dec'']","commission":"Birding/chocolate/canopy affiliate + lodge night","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"culture":"destination","expedition":"primary"},"commission_lane":["affiliate","hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Papallacta thermal springs","si_tag":"expedition","tier":"essential","source":"https://destinationlesstravel.com/day-trips-from-quito/","timing":"year-round","timing_type":"ALWAYS-ON","hook":"high-páramo volcanic hot springs 1h30 east, framed by mountains; the perfect post-climb recovery day","si":"expedition","blurb":"high-páramo volcanic hot springs 1h30 east, framed by mountains; the perfect post-climb recovery day","when":"year-round","commission":"Day-trip transport + spa-hotel affiliate","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"culture":"destination","expedition":"primary"},"commission_lane":["affiliate","hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Otavalo market + Cotacachi/Cuicocha","si_tag":"Romance & Heritage","tier":"essential","source":"https://destinationlesstravel.com/day-trips-from-quito/","timing":"[''Jun'', ''Jul'', ''Aug'', ''Sep'', ''Dec'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"South America''s most famous handicraft market, 2+ hrs north; pair with the crater-lake Laguna de Cuicocha at the foot of Cotacachi volcano","si":"romance","blurb":"South America''s most famous handicraft market, 2+ hrs north; pair with the crater-lake Laguna de Cuicocha at the foot of Cotacachi volcano","when":"[''Jun'', ''Jul'', ''Aug'', ''Sep'', ''Dec'']","commission":"Cultural day-trip DMC","wells":["activities","eat","shop"],"wells_basis":"pass 2 — text","si_all":["Romance & Heritage","culture","romance"],"shelf_fit":{"Romance & Heritage":"evidenced","culture":"evidenced","romance":"primary"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane","si_raw":"Romance & Heritage","si_map_basis":"normalised from free text ''Romance & Heritage'' by gen_normalise_jewel_si"}],"faq":[{"q":"Why is Quito''s Old Town so famous?","a":"Because it was the first UNESCO World Heritage Site ever inscribed, in 1978 (alongside Kraków), and remains the largest, best-preserved historic center in the Americas. Its jewel is La Compañía de Jesús, whose central nave is almost entirely covered in gold leaf after 160 years of construction (1605–1765); entry is ~$5.","source":"quitotrip.com, 2026-07-07","si_tag":"culture-&-heritage-—-future-si"},{"q":"What are the best adventure day trips from Quito?","a":"Quito is the launchpad for high-altitude Andes adventure. Top picks: Cotopaxi (5,897 m active volcano, 1h45 south), Quilotoa''s 250 m-deep turquoise crater lake (~3-hr drive) and Mindo''s 500+ bird species two hours northwest, with cloud-forest ziplines, waterfalls and tubing. Volcano climbs are guided-only.","source":"destinationlesstravel.com, 2026-07-07","si_tag":"expedition"},{"q":"Where do couples stay near Quito for a romantic Andes escape?","a":"In restored colonial mansions or working-estate haciendas. The 10-room Illa Experience Hotel in the San Marcos creative quarter is an intimate couples'' retreat steps from the Old Town sights, while the 17th-century Hacienda Zuleta at ~2,900 m, ~2 hrs north, offers horseback riding and whole-estate buyouts for weddings.","source":"scottdunn.com, 2026-07-07","si_tag":"romance"},{"q":"Is Quito just a stopover for Galápagos?","a":"It is the essential gateway, and worth a night or two in its own right. Quito''s Mariscal Sucre (UIO) is the primary air gateway feeding Galápagos and the Amazon, so most Quito nights ride the bigger cruise curve as a pre/post-Galápagos stay; at 2,850 m (9,350 ft) the city also doubles as the acclimatization night before the Andes.","source":"greengotravel.com, 2026-07-07","si_tag":null},{"q":"What''s the real risk to plan for in Quito?","a":"Altitude, not crime. ~88% of Ecuador''s homicides occur in five coastal provinces and Quito''s homicide rate runs below many mid-sized US cities; the real headline is that the city sits at 2,850 m (9,350 ft), where mild AMS is common within 24 hours of arrival — arrive, hydrate, go slow on day 1, skip alcohol, and acclimatize before any climb.","source":"myecuadorvisa.com, 2026-07-07","si_tag":"safety"},{"q":"Is climbing Cotopaxi dangerous?","a":"Yes — it is mountaineering, guided-only. Cotopaxi (5,897 m) involves glacier travel, crevasse risk and real HAPE/HACE exposure; it requires a certified mountain guide, a rope team, 2–3 days of prior acclimatization at 3,000–3,500 m, and evacuation insurance. Never freelance it — even Rucu Pichincha (~4,700 m) deposits you at 4,000 m with no acclimatization.","source":"fairtravel4u.org, 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Quito & the Northern Andes, Ecuador — UNESCO Old Town, Cotopaxi & Cloud Forest | TravelWell","jsonld_type":"TouristDestination","search_language":"es-EC","local_keywords":["qué hacer en Quito","Centro Histórico Quito","Cotopaxi tour","Mitad del Mundo","mercado de Otavalo","laguna Quilotoa","bosque nublado Mindo","termas de Papallacta","TelefériQo Quito"],"hreflang":["en","es-EC"],"primary_keyword":"Quito & the Northern Andes","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-20","last_verified_basis":"safety.fcdo.read","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/ecuador","read":"2026-08-20T14:53:32Z","source_updated":"2026-07-10T10:44:44+01:00"}]},"content_freshness":"2026-07-07"},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"culture","status":"live"}],"ultra":[{"name":"Casa Gangotena","category":"Relais & Châteaux boutique, Old Town","mor":"Virtuoso / Relais & Châteaux","tier":"$$$$"},{"name":"Mashpi Lodge","category":"Cloud-forest ultra-lodge","mor":"Virtuoso / DMC package","tier":"$$$$"},{"name":"Illa Experience Hotel","category":"10-key boutique, San Marcos","mor":"Virtuoso / luxury specialist","tier":"$$$$"},{"name":"Hacienda Zuleta","category":"Historic working estate ~2,900m","mor":"Virtuoso / DMC","tier":"$$$-$$$$"},{"name":"Hacienda La Danesa","category":"Luxury working hacienda","mor":"Virtuoso / DMC","tier":"$$$-$$$$"}],"source_verified":null,"hero":{"query":"Quito & the Northern Andes, Ecuador, Ecuador"},"geo":{"lat":-0.1807,"lng":-78.4678},"orbit":[{"id":"banos-ecuador","jewels":9,"si":["wellness","romance"]},{"id":"cuenca-ecuador","jewels":10,"si":["culture"]},{"id":"galapagos-islands-ecuador","jewels":12,"si":["liveaboard","expedition"]}],"orbit_country":[]}'::jsonb, 93),
