"name":"Lake Coatepeque (volcanic caldera lake)","si_tag":"expedition","tier":"comfort","source":"https://www.booking.com/city/sv/coatepeque.html | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"Dry season Nov–Apr","commission":"Lakeside boutique-hotel bookings (Cardedeu/Equinoccio) + boat excursions via operator","accessed":"2026-07-07","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"culinary":"destination","culture":"destination","expedition":"primary"},"commission_lane":["operator","hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Apaneca Laguna Verde + Enganches/Ausol canopy zipline","si_tag":"expedition","tier":"essential","source":"https://www.visitelsalvador.ai/blog/ruta-de-las-flores-guide-complet-villages | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Crater lake ~5 km from Apaneca plus Central America''s longest cloud-forest ziplines","si":"expedition","blurb":"Crater lake ~5 km from Apaneca plus Central America''s longest cloud-forest ziplines","when":"Dry season Nov–Apr","commission":"DMC/operator activity affiliate","accessed":"2026-07-07","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"culinary":"destination","culture":"destination","expedition":"primary"},"commission_lane":["operator","DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Los Chorros de la Calera / Siete Cascadas waterfall hike (Juayúa)","si_tag":"expedition","tier":"essential","source":"https://www.visitelsalvador.ai/blog/ruta-de-las-flores-guide-complet-villages | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Terraced falls with cliff jumps and rappels. The 7 Waterfalls hike requires a mandatory guide — flash-flood, slick-rock, and cliff-jump hazards make guided mandatory","si":"expedition","blurb":"Terraced falls with cliff jumps and rappels. The 7 Waterfalls hike requires a mandatory guide — flash-flood, slick-rock, and cliff-jump hazards make guided mandatory","when":"Dry season Nov–Apr","commission":"Local guide via DMC; commissionable through operator (guided-only)","accessed":"2026-07-07","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"culinary":"destination","culture":"destination","expedition":"primary"},"commission_lane":["operator","DMC","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Concepción de Ataco street art + coffee","si_tag":"culture","tier":"essential","source":"https://www.visitelsalvador.ai/blog/ruta-de-las-flores-guide-complet-villages | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"El Salvador''s most photogenic mural town — indigenous-history murals, Mirador de la Cruz, indigo-dye workshops, weekend street festival","si":"culture","blurb":"El Salvador''s most photogenic mural town — indigenous-history murals, Mirador de la Cruz, indigo-dye workshops, weekend street festival","when":"Dry season Nov–Apr","commission":"Mural-walk + coffee-finca combo via DMC; workshop fees via operator","accessed":"2026-07-07","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary"},"commission_lane":["operator","DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Nahuizalco Mercado Nocturno (night market)","si_tag":"culture","tier":"essential","source":"https://www.visitelsalvador.ai/blog/ruta-de-las-flores-guide-complet-villages | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"One of the few places you''ll see women in traditional Pipil dress; wicker-craft workshops and a rare evening artisan market","si":"culture","blurb":"One of the few places you''ll see women in traditional Pipil dress; wicker-craft workshops and a rare evening artisan market","when":"Dry season Nov–Apr","commission":"Evening add-on to route itinerary; craft purchases direct","accessed":"2026-07-07","wells":["stay","activities","shop"],"wells_basis":"derived from name/blurb/hook","si_all":["culinary","culture"],"shelf_fit":{"culinary":"evidenced","culture":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Joya de Cerén — Pompeii of the Americas (UNESCO)","si_tag":"culture","tier":"essential","source":"https://www.viator.com/San-Salvador-attractions/Joya-de-Ceren-Archaeological-Site/d5585-a15755 | Accessed 2026-07-07","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"A 7th-century Maya farming village buried and preserved by volcanic ash; El Salvador''s only UNESCO World Heritage site. Open 9–4, closed Mondays; on-site museum","si":"culture","blurb":"A 7th-century Maya farming village buried and preserved by volcanic ash; El Salvador''s only UNESCO World Heritage site. Open 9–4, closed Mondays; on-site museum","when":"Dry season Nov–Apr","commission":"Guided heritage day trip via DMC/Viator; site entry non-commissionable","accessed":"2026-07-07","wells":["stay","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary"},"commission_lane":["DMC","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Tazumal ruins (Chalchuapa)","si_tag":"culture","tier":"essential","source":"https://andysworldjourneys.com/2025/10/16/joya-de-ceren-and-tazumal-ancient-history-in-el-salvador/ | Accessed 2026-07-07","timing":"year-round","timing_type":"ALWAYS-ON","hook":"El Salvador''s most important pyramids/ceremonial platforms, ~40 min from Joya de Cerén — the two pair into one Maya-heritage day","si":"culture","blurb":"El Salvador''s most important pyramids/ceremonial platforms, ~40 min from Joya de Cerén — the two pair into one Maya-heritage day","when":"year-round","commission":"Combined Maya-heritage day trip w/ Joya de Cerén via DMC/operator; entry non-commissionable","accessed":"2026-07-07","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary"},"commission_lane":["operator","DMC"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What is the Juayúa food festival?","a":"The Feria Gastronómica is the route''s flagship weekend market: every Saturday and Sunday, 11am–5pm, free entry, cash only, with the plaza filling with grills and pots — grilled meats $6–9, seafood ~$7, soups $3–4, pupusas ~$0.60, and roughly $10–20 feeds one person across multiple dishes. *[Culinary]*","source":"visitelsalvador.ai, Accessed 2026-07-07","si_tag":"culinary"},{"q":"Is Joya de Cerén worth visiting?","a":"Yes — it is El Salvador''s only UNESCO World Heritage site, a 7th-century Maya farming village buried and preserved by volcanic ash, earning the name \"Pompeii of the Americas.\" Open 9–4 and closed Mondays with an on-site museum, it pairs with the Tazumal ruins (~$5 entry, ~40 min away) into one Maya-heritage day. *[Culture & Heritage]*","source":"viator.com + andysworldjourneys.com, Accessed 2026-07-07","si_tag":"culture"},{"q":"Is the Santa Ana volcano hike dangerous?","a":"It is managed, not casual. Santa Ana (Volcán Ilamatepec, 2,381 m) is an active, monitored volcano with a turquoise sulphur crater lake and volcanic gas near the rim; the ~4–5 hour summit hike is guided-only, at scheduled departure times, and is subject to closure on activity alerts. Do not attempt it unguided, and confirm open status before booking.","source":"sallysees.com, Accessed 2026-07-07","si_tag":"safety"},{"q":"What outdoor adventures are on the Ruta de las Flores?","a":"The GEA spine runs from Santa Ana''s turquoise crater and Cerro Verde to Lake Coatepeque (a volcanic caldera lake beneath the volcano), plus Apaneca''s cloud-forest canopy ziplines (Los Enganches ~420 m lines) and the Laguna Verde crater lake ~5 km from Apaneca. Waterfall hikes at Los Chorros / Siete Cascadas round it out. *[GEA]*","source":"visitelsalvador.ai + sallysees.com, Accessed 2026-07-07","si_tag":"expedition"},{"q":"Where do couples stay on the Ruta de las Flores?","a":"Two romance bookends: coffee-finca boutique on the route itself — Hotel Santa Leticia, a 19-room working-estate lodge from ~USD 78/night — or lakeside luxe on Lake Coatepeque, where Cardedeu Residence is a 5-star hotel and Equinoccio a boutique lakeside stay with balcony rooms over the water. There is no international five-star flag on the route. *[Romance]*","source":"lastfrontiers.com + booking.com, Accessed 2026-07-07","si_tag":"romance"},{"q":"What''s the real risk to plan for?","a":"Guided-only adventure and mountain roads. The Siete Cascadas 7-waterfall hike (~6 hrs) requires a mandatory guide (~$15/person) because of flash-flood, slick-rock, and cliff-jump hazards; canopy ziplines are operator-run with harness and briefing. The route itself is a cobblestone-and-switchback mountain drive — go in daylight, watch for highland fog, and prefer a local driver at night.","source":"visitelsalvador.ai, Accessed 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Ruta de las Flores, El Salvador — Coffee Towns, Santa Ana Volcano & the Flower Route | TravelWell.World","jsonld_type":"TouristDestination","search_language":"es-SV","local_keywords":["Ruta de las Flores El Salvador","Volcán Santa Ana","Juayúa festival gastronómico","Concepción de Ataco murales","Laguna Verde Apaneca","tour de café Ruta de las Flores","Lago de Coatepeque hotel","Joya de Cerén Pompeya de América"],"hreflang":["en","es-SV"],"primary_keyword":"Ruta de las Flores","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-20","last_verified_basis":"safety.fcdo.read","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/el-salvador","read":"2026-08-20T14:53:55Z","source_updated":"2026-06-17T14:04:09+01:00"}]},"content_freshness":"2026-07-07"},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"culture","status":"live"},{"si":"culinary","status":"live"}],"ultra":[{"property":"Hotel & Restaurante Santa Leticia (Apaneca)","note":"Boutique coffee-finca ceiling on the route itself; 19 rooms, on-farm coffee program","earning":"hotel commission via consortia/bedbank","mor":"hotel/OTA","tier":"$$–$$$"},{"property":"Cardedeu (5-star) / Equinoccio + private villas, Lake Coatepeque","note":"Caldera-lake luxe bookend under Santa Ana","earning":"hotel commission (Cardedeu/Equinoccio); villas referral/affiliate only","mor":"hotel for flags; Airbnb/VRBO for villas","tier":"$$$–$$$$"},{"property":"San Salvador city 5-star bookend","note":"Arrival/departure luxe anchor; where international-flag commission lives (verify availability)","earning":"hotel commission via preferred/Virtuoso program","mor":"hotel","tier":"$$$–$$$$"}],"source_verified":null,"hero":{"query":"Ruta de las Flores, El Salvador, El Salvador"},"geo":{"lat":13.8722,"lng":-89.7928},"orbit":[{"id":"suchitoto-el-salvador","jewels":10,"si":["romance","expedition","culture"]}],"orbit_country":[]}'::jsonb, 97)
