  ('san-andres-colombia', '10S', 'San Andrés & Providencia, Colombia', 'Colombia', 'Coral islet, seven-colour sea', 'live', 'verified', 'tropicalBeach', 'Colombia''s Caribbean Coast', '{"tropical","liveaboard","romance","culture"}', '{"tropical"}', '{"essential","premier","luxury"}', null, null, '{"key_facts":["San Andrés — the ''Sea of Seven Colors'' — is Colombia''s Caribbean crown jewel, ringed by coral with 40+ mostly-shallow, high-visibility dive sites.","Providencia + Santa Catalina sit on the third-largest barrier reef in the world; Providencia rebuilt after Hurricane Iota (2020) and is open to tourism in 2026.","The Raizal are a Black Colombian Afro-Caribbean people; 20,000–30,000 speak San Andrés–Providencia Creole (Islander English) and most are trilingual.","Rondón — fish, conch, cassava, plantain and yam simmered in coconut milk — is the island''s signature dish (''run down'').","Mandatory Tourist Card (Tarjeta de Turismo) ~COP 153,000 (2026), bought at the airline counter before boarding the flight to ADZ."],"safety":{"emergency":"123","hospital":"Hospital Departamental Clarence Lynd Newball (San Andrés); hyperbaric/decompression chamber at Timothy Britton Hospital, San Andrés; serious cases referred off-island to mainland or US","book_enabled":true,"risk_codes":["C","T","U","K","N"],"risk_code_meanings":{"C":"Crime — violent crime (murder, assault, robbery), drugging (scopolamine/burundanga), extortion, express kidnapping occur throughout Colombia incl. cities (island crime skews to petty/beach theft + motorcycle snatch-and-grab)","T":"Terrorism — attacks possible with little/no warning; car bombs, grenades, IEDs, drones (mainland-weighted)","U":"Unrest — demonstrations can shut roads and turn violent","K":"Kidnapping or Hostage-Taking — kidnapping-for-ransom reported (mainland-weighted)","N":"Natural Disaster — mainland volcano/earthquake/landslide; archipelago hurricane/tropical-storm exposure (Hurricane Iota, Nov 2020)"},"named_danger":["Arauca","Cauca excl Popayán","Valle del Cauca excl Cali","Norte de Santander","Venezuela border ~10km"],"archipelago_in_named_danger":false,"island_crime_note":"island petty-crime (beach theft, motorcycle snatch-and-grab, scooter accidents) is lower and different from mainland violent crime; country-level advisory still renders in full at consent","air_access_verified":"ADZ (Gustavo Rojas Pinilla Intl) — direct international from Panama City (Copa, year-round) + domestic Colombian hubs; no nonstop US, but 1-stop via BOG/PTY (Avianca, Copa, LATAM). Providencia reached by ~20-min inter-island flight or catamaran.","remote_flag":true,"water":"bottled","vaccinations":"dengue/chikungunya/Zika present (peak rainy months); use insect protection; check CDC","scopolamine_caution":"''devil''s breath''/burundanga drugging — country-level; concentrates on mainland; never accept drinks/food from strangers","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/colombia","read":"2026-08-20T14:47:41Z","page_updated":"2026-08-18T15:51:11+01:00","source_country":"colombia","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"fcdo_zones":[{"name":"all of Norte de Santander Department, including Cúcuta","lvl":3,"posture":"all-but-essential"},{"name":"all of Arauca Department","lvl":3,"posture":"all-but-essential"},{"name":"the municipality of Puerto Carreño in Vichada Department","lvl":3,"posture":"all-but-essential"},{"name":"within 5km of the rest of the border with Venezuela","lvl":3,"posture":"all-but-essential","note":"The FCDO separately advises against all travel to Venezuela''s side of the border — do not use any Colombia-Venezuela land crossing."},{"name":"Chocó Department","lvl":3,"posture":"all-but-essential","except":["the department capital Quibdó","the towns of Nuquí and Bahía Solano","Capurganá"]},{"name":"the western part of Valle del Cauca Department, including Buenaventura","lvl":3,"posture":"all-but-essential"},{"name":"the municipality of Jamundí, Valle del Cauca","lvl":3,"posture":"all-but-essential"},{"name":"the South Pacific, Sanquianga and Telembi regions of Nariño Department","lvl":3,"posture":"all-but-essential"},{"name":"the southern part of Córdoba Department","lvl":3,"posture":"all-but-essential"},{"name":"the Urabá and Bajo Cauca regions of Antioquia Department","lvl":3,"posture":"all-but-essential"},{"name":"the southern part of Bolívar Department","lvl":3,"posture":"all-but-essential"},{"name":"all of Guaviare Department","lvl":3,"posture":"all-but-essential","except":["the department capital San José del Guaviare"]},{"name":"Cartagena del Chairá, San Vicente del Caguan, Puerto Rico, El Doncello, Paujil and La Montañita in Caquetá Department","lvl":3,"posture":"all-but-essential"},{"name":"the Ariari region of southern Meta","lvl":3,"posture":"all-but-essential","except":["Caño Cristales"],"note":"If travelling to Caño Cristales, the FCDO advises travelling by air from the town of La Macarena with a reputable tour company."},{"name":"within 5km of the border with Ecuador","lvl":3,"posture":"all-but-essential","except":["the border crossing on the Pan-American highway at the Puente Internacional de Rumichaca","the city of Ipiales in Nariño Department"]},{"name":"all of Cauca Department","lvl":3,"posture":"all-but-essential","except":["the department capital Popayán"],"note":"The advisory page nests Cauca inside its Ecuador-border sentence; we hold it as a restricted department in its own right — the stricter of the two readings, consistent with the FCDO''s regional-risks detail."},{"name":"Orito, San Miguel, Valle del Guamuez, Puerto Caicedo, Puerto Guzmán, Puerto Asis and Puerto Leguizamo in Putumayo Department","lvl":3,"posture":"all-but-essential"}]},"timing":{"peak":"Dec–Apr (dry); true peak January, then Feb–Mar (Colombians'' favorite domestic island)","inflection_curve_start":"early December","fire_date":"mid-to-late Novembe