veaboards / Diving","diveglobal","liveaboard","tropical"],"shelf_fit":{"Dive Liveaboards / Diving":"evidenced","culture":"destination","diveglobal":"evidenced","liveaboard":"primary","romance":"destination","tropical":"evidenced"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane","si_raw":"Dive Liveaboards / Diving","si_map_basis":"normalised from free text ''Dive Liveaboards / Diving'' by gen_normalise_jewel_si"},{"name":"Providencia barrier reef (third-largest on earth)","si_tag":"Dive Liveaboards / Diving","tier":"premier","source":"https://colombia.travel/en/providencia","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"wall and reef diving off Providencia/Santa Catalina, wilder and less-visited than San Andrés","si":"liveaboard","blurb":"wall and reef diving off Providencia/Santa Catalina, wilder and less-visited than San Andrés","when":"Dec–Apr","commission":"Providencia dive operator direct + inter-island flight","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["Dive Liveaboards / Diving","diveglobal","liveaboard","tropical"],"shelf_fit":{"Dive Liveaboards / Diving":"evidenced","culture":"destination","diveglobal":"evidenced","liveaboard":"primary","romance":"destination","tropical":"evidenced"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane","si_raw":"Dive Liveaboards / Diving","si_map_basis":"normalised from free text ''Dive Liveaboards / Diving'' by gen_normalise_jewel_si"},{"name":"Providencia + Crab Cay + McBean Lagoon","si_tag":"romance","tier":"premier","source":"https://cuppatocopatravels.com/south-america/colombia/guide-isla-de-providencia-colombia/","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the quiet-honeymoon jewel: Crab Cay ranked the island''s 1 snorkel spot, the McBean Lagoon marine park, near-empty coves","si":"romance","blurb":"the quiet-honeymoon jewel: Crab Cay ranked the island''s 1 snorkel spot, the McBean Lagoon marine park, near-empty coves","when":"Dec–Apr","commission":"Providencia DMC/boutique + marine-park fee (non-comm)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["romance","tropical"],"shelf_fit":{"culture":"destination","liveaboard":"destination","romance":"primary","tropical":"evidenced"},"commission_lane":["DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"San Luis sunset stays","si_tag":"romance","tier":"essential","source":"https://colombia.travel/en/san-andres-island/native-inns","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the mellow east-coast beach strip, sunset-side quiet, small hotels and native inns for a low-key honeymoon","si":"romance","blurb":"the mellow east-coast beach strip, sunset-side quiet, small hotels and native inns for a low-key honeymoon","when":"Dec–Apr","commission":"San Luis hotel affiliate + host","wells":["stay"],"wells_basis":"derived from name/blurb/hook","si_all":["romance","tropical"],"shelf_fit":{"culture":"destination","liveaboard":"destination","romance":"primary","tropical":"evidenced"},"commission_lane":["affiliate","hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Raizal culture + Islander Creole","si_tag":"culture","tier":"essential","source":"https://en.wikipedia.org/wiki/Raizal","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"a living Afro-Caribbean nation: Creole English, Baptist chapels, kinship ties across the western Caribbean","si":"culture","blurb":"a living Afro-Caribbean nation: Creole English, Baptist chapels, kinship ties across the western Caribbean","when":"Dec–Apr","commission":"cultural-tour affiliate + native-inn stay","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["culture","tropical"],"shelf_fit":{"culture":"primary","liveaboard":"destination","romance":"destination","tropical":"evidenced"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Rondón + coconut cuisine","si_tag":"culture","tier":"essential","source":"https://colombiaone.com/2025/09/02/colombia-food-san-andres/","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the \"run down\" seafood-in-coconut-milk stew, breadfruit, crab, conch; a Raizal food-and-culture experience","si":"culture","blurb":"the \"run down\" seafood-in-coconut-milk stew, breadfruit, crab, conch; a Raizal food-and-culture experience","when":"Dec–Apr","commission":"food-tour affiliate + restaurant","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","liveaboard":"destination","romance":"destination","tropical":"destination"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Morgan''s Cave","si_tag":"culture","tier":"essential","source":"https://colombiaone.com/2023/12/21/guide-visit-san-andres-island-colombia/","timing":"Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"legendary Henry Morgan pirate-treasure hideout, now a small theme park/museum with exhibits and dance shows","si":"culture","blurb":"legendary Henry Morgan pirate-treasure hideout, now a small theme park/museum with exhibits and dance shows","when":"Dec–Apr","commission":"island-tour affiliate + entry (non-comm)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","liveaboard":"destination","romance":"destination","tropical":"destination"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What are the best beaches and cays on San Andrés?","a":"Johnny Cay is the headline — a protected 4-ha coral islet ~1.5 km off San Andrés Town with the best white sand around, reached by colectivo boat — plus calm snorkel pools at La Piscinita and West View, and mellow Rocky Cay off San Luis. The lagoon is the famed \"Sea of Seven Colors.\"","source":"lonelyplanet.com, 2026-07-07","si_tag":"tropical"},{"q":"Is San Andrés good for scuba diving?","a":"Yes — it''s a shallow-water reef diver''s dream, with 40+ dive sites mostly at ~10–12 m, high-visibility and beginner-friendly, run through island PADI centers like Banda and Sharky. Providencia adds wall diving on the third-largest barrier reef in the world. Note it''s day-boat reef diving, not liveaboard-berth product.","source":"divescover.com, 2026-07-07","si_tag":"liveaboard"},{"q":"Is Providencia good for a quiet honeymoon?","a":"Yes — Providencia is the quiet-honeymoon jewel: near-empty coves, the McBean Lagoon marine park, and Crab Cay (its #1 snorkel spot, ~USD $6 park fee) reached by express boat. It''s rebuilt and open after Hurricane Iota (2020); reach it by ~20-minute inter-island flight or catamaran.","source":"cuppatocopatravels.com, 2026-07-07","si_tag":"romance"},{"q":"What language and culture will I find on San Andrés?","a":"A living Raizal Afro-Caribbean nation: 20,000–30,000 people speak San Andrés–Providencia Creole (Islander English) and most are trilingual, descended from 18th-century Jamaican settlers and enslaved Africans. The signature plate is rondón — fish, conch and root vegetables simmered in coconut milk.","source":"en.wikipedia.org, 2026-07-07","si_tag":"culture"},{"q":"What''s the real day-to-day risk on the island?","a":"Not the mainland headlines — the island''s real risks are petty/beach theft, motorcycle snatch-and-grab, scooter accidents and sea/riptide hazards. Renting a scooter or golf cart is the classic island loop, and scooter crashes plus snatch-and-grab are the two most common tourist mishaps: helmet on, valuables off the seat, drive in daylight.","source":"travelsafe-abroad.com, 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"San Andrés & Providencia, Colombia — Sea of Seven Colors Diving, Beaches & Raizal Culture | TravelWell.World","jsonld_type":"TouristDestination","search_language":"es-CO","local_keywords":["San Andrés qué hacer","buceo San Andrés","Providencia","tarjeta de turismo San Andrés","Johnny Cay San Andrés","Cueva de Morgan","rondón San Andrés"],"hreflang":["en","es-CO"],"attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-20","last_verified_basis":"safety.fcdo.read","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/colombia","read":"2026-08-20T14:47:41Z","source_updated":"2026-08-18T15:51:11+01:00"}]},"content_freshness":"2026-07-07","long_tail":["things to do in San Andres Colombia","San Andres diving Sea of Seven Colors","is San Andres safe 2026","Providencia island Colombia guide","San Andres tourist card cost 2026","Johnny Cay day trip San Andres","Providencia Crab Cay snorkeling"]},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":["tropical","Dive Liveaboards / Diving","romance","culture"],"ultra":[{"name":"Casa Harb","type":"design boutique — island top-end (luxury, NOT palace-ultra)","routing":"Fora/Virtuoso preferred where participating + host","tier":"luxury"},{"name":"Decameron cluster (Isleño/San Luis/Los Delfines/Aquarium)","type":"mass-market all-inclusive","routing":"Online-Agency (OA) lane + host","tier":"premium (mass AI)"},{"name":"GHL Sunrise Hotel (Sunrise Beach)","type":"mid-market beachfront workhorse, Spratt Bight","routing":"GDS/bedbank + host","tier":"premier"},{"name":"Casa Iguana del Mar (villa)","type":"award-winning design villa, reef + white sand","routing":"MoR villa + host","tier":"luxury (thin)"},{"name":"Deep Blue (Providencia)","type":"boutique standout, Crab Cay gateway","routing":"direct/host","tier":"premium (remote boutique)"}],"source_verified":null,"hero":{"query":"San Andrés & Providencia, Colombia, Colombia"},"geo":{"lat":12.5847,"lng":-81.7006},"orbit":[{"id":"cartagena-colombia","jewels":12,"si":["romance","tropical","culture"]}],"orbit_country":["bogota-colombia","medellin-colombia"]}'::jsonb, 100),
