  ('san-cristobal-de-las-casas-mexico', '10S', 'San Cristóbal de las Casas, Mexico', 'Mexico', 'San Cristóbal de las Casas', 'live', 'verified', 'kyoto', 'Chiapas (San Cristóbal & Palenque)', '{"culture"}', '{}', '{"essential","comfort","luxury","ultra"}', null, null, '{"key_facts":null,"safety":{"emergency":"911","advisory_named_area_language":"US govt employees may travel to Tapachula (city limits, S/W of Hwy 200); may NOT travel to municipality of Ocozocoautla; may NOT travel to Southeastern Chiapas polygon (Guatemala border Pacific->Netzahualcoyotl->Ocosingo->El Ocote->San Francisco Pujiltic->Mapastepec, E/N of Hwy 200). San Cristobal / Tuxtla / Chiapa de Corzo fall OUTSIDE named boundaries.","gate_decision":"BOOK WITH WARNING","book_enabled":true,"content_only":false,"air_access_verified":true,"air_access_note":"Tuxtla Gutierrez TGZ (Angel Albino Corzo Intl) ~77km / ~1h05-1h30 to San Cristobal via Hwy 190/190D; corridor outside restricted zone","road_safety_flag":"Hwy 199 San Cristobal<->Palenque via Ocosingo: reported armed robbery (mostly night) + CNTE blockades — daytime-only, guided/private transfer","altitude":"~2200m, mild","water":"bottled/purified only","dengue":"lowland concern (Palenque/jungle/canyon), not highland city","founder_attorney_flag":"consent-flow wording pending compliance-attorney sign-off; re-verify advisory before each fire and before live checkout","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","page_updated":"2026-07-16T16:08:09+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}]},"timing":{"peak":["Nov-Apr dry season","Dia de Muertos (Oct 31-Nov 2)","Semana Santa (2026: Mar 29-Apr 5)"],"inflection":"6-10 weeks pre-peak; boutique tier sells 8-12 weeks out","fire_date":"curve-start minus 1-2 weeks (dry-season fire ~mid-Sep; Dia de Muertos fire ~early-mid Oct","off_season_specials":"May-Oct green/rainy value window; culture fully accessible year-round; highland climate never hot"},"jewels":[{"name":"Andadores + Templo de Santo Domingo + Museo del Ámbar","si_tag":"culture","tier":"essential","source":"https://randomtrip.net/san-cristobal-de-las-casas-travel-guide-chiapas-mexico/","timing":"[''Nov-Apr dry season'', ''Dia de Muertos '', ''Semana Santa '']","when_source":"derived from destination timing","timing_type":"SEAS