  ('sayulita-mexico', '10S', 'Sayulita & the Riviera Nayarit', 'Mexico', 'Nayarit''s boho surf pueblo magico', 'live', 'verified', 'tropicalBeach', 'Nayarit (Riviera Nayarit & Sayulita)', '{"tropical","expedition","romance","ocean","culture","family","wildlife"}', '{"tropical"}', '{"essential","comfort","luxury"}', null, null, '{"key_facts":["Sayulita is a Pueblo Magico (since 2015) and the boho surf-and-art anchor of the southern Riviera Nayarit.","Bahia de Banderas filters Pacific swell into a forgiving 2-4 ft sand-bottom beach break - one of Mexico''s best beginner surf classrooms.","Islas Marietas ''hidden beach'' (Playa del Amor) is permit-capped: ~116 people/day, closed Mondays and Tuesdays, licensed operators only, no self-swim, life jacket + no fins, no under-10s or over-65s.","Humpback whales fill Banderas Bay roughly mid-December to early April, peak January-February.","Sayulita''s rapid growth outran its sewage infrastructure; major upgrades and an offshore outfall have been built, beach under permanent sanitary surveillance - drink bottled water, swim the protected Los Muertos cove.","Air access via Puerto Vallarta International (PVR), ~24 miles / 38-60 min south."],"safety":{"emergency":"911","hospital":"Nearest full trauma: Puerto Vallarta private hospitals (CMQ / San Javier / Hospital Joya), ~40-60 min south; local Sayulita/Bucerias clinics stabilize/transfer; complex cases PVR -> US/Guadalajara air-evac","book_enabled":true,"air_access_verified":true,"air_access_note":"Puerto Vallarta International (PVR), ~24 mi / 38-60 min south, in Jalisco but the regional gateway","riptides":"main beach + Los Muertos mellow; Patzcuarito/Carricitos open-Pacific and rip-prone (unsafe for beginner swimmers)","water":"bottled/purified only","dengue":"endemic seasonal risk, higher May-November","malaria":"not a practical risk in the tourist corridor","hurricane":"Pacific storm season ~June-October; insure/refundable summer rates","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","page_updated":"2026-07-16T16:08:09+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}]},"timing":{"peak":"Dec-Apr (dry season; whales Dec-Mar peak Jan-Feb; surf year-round; highest rates + crowds)","inflection":"November (dry weather arrives, thinner crowds, whales opening) and late April (emptying out)","green":"May-Oct (rainy/value; ~20-40% off; warmest ocean; calm beginner surf)","fire_date":"curve-start minus 1-2 weeks: open peak (Dec-Apr) campaigns early October; whale-season push early November; Semana Santa campaign by mid-January; green-season value push ~2 weeks before the May shoulder edge","fill_the_beds":"green months: lead beginner surf (calmest/warmest water), long-stay villa value, yoga/wellness retreats, Huichol workshops, San Pancho calm; hedge whale messaging until December","event_peaks":["Christmas week","New Year","Semana Santa (late Mar/early Apr - verify calendar)"],"booking_lead":"peak/holiday 3-5 months; shoulder (Nov/late-Apr) 2-4 months; green season near-walk-up"},"jewels":[{"name":"Sayulita main beach + Calle Delfines flag street","si_tag":"Tropical / Beaches","status":"live","tier":"essential","hook":"The town''s surf-beach heart under hundreds of papel-picado flags - go early.","bookable_category":"village stay + surf lesson","source":"https://themexicoedit.com/things-to-do-in-sayulita-mexico/","si":"tropical","blurb":"The town''s surf-beach heart under hundreds of papel-picado flags - go early.","commission":"boutique-AOR + surf-operator affiliate; beach access pass-through","wells":["stay","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["Tropical / Beaches","ocean","tropical"],"shelf_fit":{"Tropical / Beaches":"evidenced","culture":"destination","expedition":"destination","family":"destination","ocean":"evidenced","romance":"destination","tropical":"primary","wildlife":"destination"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane","si_raw":"Tropical / Beaches","si_map_basis":"normalised from free text ''Tropical / Beaches'' by gen_normalise_jewel_si"},{"name":"Playa de los Muertos (family swimming cove)","si_tag":"Family","status":"future","tier":"essential","hook":"Rock-protected roped swim area, no surf/boat traffic - the safe kids'' bea