carmen-mexico","puerto-aventuras-mexico","puerto-morelos-mexico","puerto-vallarta-mexico","rio-lagartos-mexico","san-cristobal-de-las-casas-mexico","san-jose-del-cabo-mexico","san-miguel-de-allende-mexico","san-sebastian-del-oeste-mexico","sian-kaan-mexico","teotihuacan-mexico","tlaquepaque-mexico","todos-santos-mexico","tulum-mexico","uxmal-mexico","valladolid-mexico","valle-de-guadalupe-mexico","puerto-escondido-mexico"]}'::jsonb, 112),
  ('semuc-champey-guatemala', '10S', 'Semuc Champey', 'Guatemala', 'Turquoise pools on a natural limestone bridge', 'live', 'verified', 'mountainValley', 'Guatemala', '{"expedition"}', '{}', '{"essential"}', 'essential', null, '{"key_facts":["Pools sit atop a natural limestone bridge over the Cahabón River, which flows beneath them; Q''eqchi'' Maya ''where the river hides under the earth''.","Dry season Nov-Apr = clearest turquoise + safe current; rainy season May-Oct can turn pools brown and flood/close the site.","Lanquín-Semuc access road fully paved (concreted) in 2025; ~20-25 min by 4x4 from Lanquín.","Park open daily 08:00-16:00; entry Q50 foreigner / Q30 national (non-commissionable).","Nearest real hospital ~4 hours away in Cobán — remote-medevac destination."],"safety":{"emergency":{"police":"110","fire_ambulance":"122","proatur_asistur":"1500 / +502 2290 2810","asistur_whatsapp":"+502 5188 1819","red_cross":"125"},"book_enabled":true,"l3_disclosure":true,"stay_in_zone":true,"air_access_verified":"via La Aurora GUA (Guatemala City) then overland Cobán-Lanquín","remote_flag":true,"remote_flag_detail":"HARD — nearest real hospital ~4 hrs away via Cobán → Guatemala City air-evac; evac-grade travel insurance mandatory; K''anba cave guided-only, no PPE; occasional protester roadblocks (consult PROATUR)","founder_policy_note":"BOOK WITH WARNING (Four-Bin v3) — founder-blessed as bookable-with-warning, with mandatory full-advisory disclosure","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/guatemala","read":"2026-08-20T14:47:53Z","page_updated":"2026-08-13T14:45:16+01:00","source_country":"guatemala","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"Within 5km of the Mexican border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"The towns of Santa Ana Huista, San Antonio Huista and La Democracia, in Huehuetenango","lvl":3,"posture":"all-but-essential"}]},"timing":{"season_shape":"dry-season destination (Nov-Apr); pools clearest and calmest, road passable","curve_start":"early-to-mid November","peak":"December-March","shoulder_green":["April","late Oct / early Nov"],"booking_lead":"2-6 weeks in peak (pressure is on limited Lanquin lodge beds, not the park)","events":"regional: Cobán Rabín Ajau folkloric festival (late Jul/early Aug, rainy season)","fire_date":"~2026-10-20 to 2026-10-27 (curve-start minus 1-2 weeks)","note":"sharpen on live tracking — curve is weather/water-coupled","off_season_specials":"May-October (water clarity + closure risk)"},"jewels":[{"name":"Turquoise pool terraces","si_tag":"expedition","tier":"essential","source":"https://www.roadaffair.com/the-ultimate-guide-to-visiting-semuc-champey/ (Accessed 2026-07-06)","timing":"December-March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"December-March","commission":"day-tour + lodge + DMC transfer commissionable; park entry non-commissionable","accessed":"2026-07-06","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"expedition":"primary"},"commission_lane":["DMC","hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"El Mirador viewpoint","si_tag":"expedition","tier":"essential","source":"https://www.roadaffair.com/the-ultimate-guide-to-visiting-semuc-champey/ (Accessed 2026-07-06)","timing":"year-round","timing_type":"ALWAYS-ON","hook":"the postcard shot of the whole terrace chain from above; GEA/photography","si":"expedition","blurb":"the postcard shot of the whole terrace chain from above; GEA/photography","when":"year-round","commission":"bundled in guided day-program","accessed":"2026-07-06","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"expedition":"primary"},"commission_lane":["bundle","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"K''anba candlelit caves (tubing)","si_tag":"expedition","tier":"essential","source":"https://www.getyourguide.com/guatemala-city-l1654/from-lanquin-semuc-champey-park-and-kanba-cave-guided-tour-t30495/ (Accessed 2026-07-06)","timing":"December-March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"December-March","commission":"guided day-tour via Viator/GetYourGuide/DMC; community cave fee non-commissionable","accessed":"2026-07-06","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"expedition":"primary"},"commission_lane":["DMC","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Lanquín Caves bat exodus (Grutas de Lanquín)","si_tag":"Wildlife/GEA","tier":"essential","source":"https://sallysees.com/semuc-champey-lanquin-guatemala/ (Accessed 2026-07-06)","hook":"Wildlife/GEA; thousands of bats stream out at sundown","si":"expedition","blurb":"Wildlife/GEA; thousands of bats stream out at sundown","commission":"add-on guided tour via lodge/DMC","accessed":"2026-07-06","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["Wildlife/GEA","expedition","wildlife"],"shelf_fit":{"Wildlife/GEA":"evidenced","expedition":"primary","wildlife":"evidenced"},"commission_lane":["DMC","hotel","guide"],"commission_embedded":false,"commission_basis":"lane","si_raw":"Wildlife/GEA","si_map_basis":"normalised from free text ''Wildlife/GEA'' by gen_normalise_jewel_si"},{"name":"Cahabón river tubing","si_tag":"expedition","tier":"essential","source":"https://www.adventurouskate.com/my-favorite-day-in-central-america-semuc-champey/ (Accessed 2026-07-06)","timing":"December-March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"December-March","commission":"outfitter/lodge day-tour (dry season only)","accessed":"2026-07-06","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["expedition"],"shelf_fit":{"expedition":"primary"},"commission_lane":["hotel","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Las Marías village + cacao/chocolate workshop","si_tag":"Culture/Wellness","tier":"essential","source":"https://utopiaecohotel.com/ (Accessed 2026-07-06)","timing":"December-March","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Culture/Wellness cross-cut; Q''eqchi'' community + Utopia''s working cacao farm chocolate-making","si":"culture","blurb":"Culture/Wellness cross-cut; Q''eqchi'' community + Utopia''s working cacao farm chocolate-making","when":"December-March","commission":"lodge-run experience (Utopia)","accessed":"2026-07-06","wells":["stay","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["Culture/Wellness","culture","wellness"],"shelf_fit":{"Culture/Wellness":"evidenced","culture":"primary","expedition":"destination","wellness":"evidenced"},"commission_lane":["hotel"],"commission_embedded":false,"commission_basis":"lane","si_raw":"Culture/Wellness","si_map_basis":"normalised from free text ''Culture/Wellness'' by gen_normalise_jewel_si"}],"faq":[{"q":"When is the best time to visit Semuc Champey?","a":"The dry season, November–April. That''s when the pools run clearest turquoise, the Cahabón current runs calm enough to swim and tube, and the now-paved road is reliably passable. Rainy season (May–October) can turn the pools muddy brown, spike current danger, and occasionally flood and close the site.","source":"adventurouskate.com, Accessed 2026-07-06","si_tag":"expedition"},{"q":"What wildlife can I see near Semuc?","a":"The signature sight is the Grutas de Lanquín bat exodus, when thousands of bats stream out at sundown — an add-on guided tour via lodge or DMC. The wider department is Alta Verapaz cloud-forest quetzal country, with the Biotopo del Quetzal reserve on the Cobán approach.","source":"sallysees.com, Accessed 2026-07-06","si_tag":"wildlife"},{"q":"What''s the real risk to plan for?","a":"Remoteness. Semuc is deep-rural: the nearest real hospital is ~4 hours away in Cobán, with no trauma center near the pools or caves, so evacuation-grade travel insurance is mandatory doctrine here. Also refuse dangerously overloaded 4×4 transfers (reports of 33 people in one truck) — book transport through a lodge or DMC.","source":"tripadvisor.com, Accessed 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Semuc Champey, Guatemala: Turquoise Pools, Caves & How to Visit (2026 Guide)","search_language":"en + es-GT","local_keywords":["cómo llegar a Semuc Champey","Semuc Champey mejor época para visitar","pozas turquesa Semuc Champey","grutas de Lanquín tour","cuánto cuesta la entrada a Semuc Champey","El Mirador Semuc Champey caminata"],"hreflang":["en","es-GT"],"jsonld_type":"TouristAttraction","content_freshness":"2026-07-06","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-06","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/guatemala","read":"2026-08-20T14:47:53Z","source_updated":"2026-08-13T14:45:16+01:00"}]}},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":["expedition"],"ultra":[{"play":"No true ultra exists; construct it — best eco-lodge (Utopia) or premier Cobán base + fully private guide + private 4x4 transfer, as one adventure day in a luxe Antigua/Atitlan/Tikal circuit","route":"Martsam (mid-luxury DMC) or Fora advisor lane for US ultra clients","manner_of_record":"sell privacy + private guiding, not a nonexistent resort"}],"source_verified":"2026-07-06","hero":{"query":"Semuc Champey, Guatemala"},"geo":{"lat":15.5342,"lng":-89.9539},"orbit":[{"id":"antigua-guatemala","jewels":12,"si":["expedition","culture","culinary","wildlife"]},{"id":"guatemala-city-guatemala","jewels":9,"si":["culture"]},{"id":"lake-atitlan-guatemala","jewels":11,"si":["adventure","romance","culture","wellness"]},{"id":"tikal-guatemala","jewels":9,"si":["expedition","culture"]}],"orbit_country":[]}'::jsonb, 113),
  ('sian-kaan-mexico', '10S', 'Sian Ka''an Biosphere Reserve', 'Mexico', '*If it''s a place the Maya named "where the', 'live', 'verified', 'oceanAerial', 'Quintana Roo (Cancún & Riviera Maya)', '{"expedition","wildlife","tropical"}', '{"tropical"}', '{"comfort","premier"}', null, null, '{"key_facts":["UNESCO World Heritage; largest reserve in Quintana Roo, ~5,000 km2 of forest/mangrove/wetland/reef","Signature: boat + life-vest float on 1,200-year-old hand-dredged Maya trade canals","Biodiversity: 300+ birds, 100+ mammals, 1,200 plants, 52 fish species","Guided-only, remote; Punta Allen coastal access ~4h on 56km unpaved road from Tulum","Fees non-commissionable: CONANP entry ~MX$218 (~US$12) + fixed Muyil boat ~MX$1,000/person"],"safety":{"emergency":"911","nearest_trauma":"Tulum/Playa del Carmen clinics; evac to Cancun for major trauma; Chetumal (south) alt","malaria":"NONE in tourist zone; dengue present - HIGH mosquito load (wetland/mangrove)","water":"bottled/purified","hurricane":"Jun-Nov, peak Aug-Oct","special_rule":"REMOTE + GUIDED-ONLY - do not enter interior independently; guides carry comms; PFD on canal float","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","page_updated":"2026-07-16T16:08:09+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}]},"timing":{"peak":"Dry season Nov-Apr (Dec-Apr optimal weather + best wildlife) - guided day-trip window","shoulder":"Nov and late-Apr edges","green":"Wet May-Oct (lush, fewer crowds, afternoon storms, hurricane overlap) - Tulum fill-the-beds","fill_the_beds":"No in-reserve beds; applies to Tulum pre/post stay - push May-Oct Tulum value + AM tours","source":"https://www.machupicchu.org/sian-kaan-biosphere-reserve-2026-unesco-world-heritage-day-trip-from-tulum.htm","fire_date":"Early-book ~6-8 weeks ahead for Dec-Apr (seats capped); green-season Tulum-stay push May-Oct","event_peaks":"Dec holiday + New Year, Semana Santa compound the capped-seat crunch","booking_lead":"2-4 weeks ahead in high season - DAILY VISITOR LIMITS cap seats (UNESCO biosphere rations access)"},"jewels":[{"name":"Muyil ancient-Maya-canal float","si_tag":"Global Expedition Adventures","status":"live","tier":"comfort","bookable_category":"guided expedition","source":"https://www.getyourguide.com/tulum-l248/tulum-sian-ka-an-biosphere-reserve-ancient-maya-canals-tour-t671649/","timing":"Dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"boat run + life-vest drift on 1,200-yr-old Maya-dredged canals ·","si":"expedition","blurb":"boat run + life-vest drift on 1,200-yr-old Maya-dredged canals ·","when":"Dry season Nov-Apr","commission":"affiliate ~4-8% (Viator/GYG) / DMC on application","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"expedition":"primary","tropical":"destination","wildlife":"destination"},"commission_pct_low":4,"commission_pct_high":8,"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Guided lagoon boat expedition","si_tag":"Global Expedition Adventures","status":"live","tier":"comfort","bookable_category":"guided boat tour","source":"https://www.mexicokantours.com/sian-kaan-adventure","si":"expedition","commission":"guided-tour affiliate / DMC (Mexico Kan Tours)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition","tropical"],"shelf_fit":{"expedition":"primary","tropical":"evidenced","wildlife":"destination"},"commission_lane":["DMC","affiliate","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Kayak + snorkel Campechen lagoon","si_tag":"Global Expedition Adventures","status":"live","tier":"comfort","bookable_category":"guided kayak/snorkel","source":"https://www.mexicokantours.com/sian-kaan-adventure","si":"expedition","commission":"affiliate/DMC","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition","tropical"],"shelf_fit":{"expedition":"primary","tropical":"evidenced","wildlife":"destination"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Birding day (300+ species)","si_tag":"Wildlife & Nature","status":"future","tier":"premier","bookable_category":"specialist nature tour","source":"https://lifeontheroam.com/sian-kaan-biosphere-reserve/","timing":"Dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"wildlife","when":"Dry season Nov-Apr","commission":"on application, small-group premium","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["wildlife"],"shelf_fit":{"expedition":"destination","tropical":"destination","wildlife":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Punta Allen coastal / sandbar","si_tag":"Tropical Islands","status":"future","tier":"comfort","bookable_category":"guided overland/boat","source":"https://www.thoroughlytravel.com/sian-kaan-biosphere-reserve/","timing":"Dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","when":"Dry season Nov-Apr","commission":"DMC/guide on application (~4h unpaved road)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["tropical"],"shelf_fit":{"expedition":"destination","tropical":"primary","wildlife":"destination"},"commission_lane":["DMC","guide"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What''s the real risk to plan for in Sian Ka''an?","a":"Remoteness, heat and mosquitoes — not marine hazards or crime. This is a mangrove/wetland reserve, so the mosquito load is high (repellent, cover up, especially dawn/dusk and rainy season), and sun, heat and dehydration are the genuine risks on a long, unpaved-road day. There is no interior infrastructure — carry water and travel with a comms-equipped guide.","source":"https://www.gov.uk/foreign-travel-advice/mexico","si_tag":"safety"},{"q":"What is the signature Sian Ka''an experience?","a":"The Muyil canal float. A boat runs you down ancient trade canals hand-dredged by Maya mariners over 1,200 years ago, then you drift downstream in a life vest on the natural current through mangrove lagoons — a natural lazy river. It is best in the calmer morning (fewer bugs), and bundled tours include transport, meals and an expert guide.","source":"getyourguide.com / lifeontheroam.com, 2026-07-04","si_tag":"expedition"},{"q":"What wildlife can I see in Sian Ka''an?","a":"A great deal — the reserve''s four ecosystems host 300+ bird species, 100+ mammals, 1,200 plants and 52 fish species, with a good chance of dolphins on the lagoon runs. Dedicated dawn birding tours are the way to see the most; wildlife is the reserve''s purpose-built anchor, so book a naturalist-guided product rather than a bare boat ride.","source":"lifeontheroam.com, 2026-07-04","si_tag":"wildlife"},{"q":"How do you actually visit Sian Ka''an, and can I stay inside?","a":"As a guided day trip from Tulum — you cannot sleep in the biosphere, as there is no lodging of any kind inside. Access is guided-only with rationed daily visitor limits, so book 2–4 weeks ahead in high season. Note the fixed Muyil boat driver is transport-only; if you want interpretation, book a nature-guide product, not the bare boat fee.","source":"machupicchu.org / roamingaroundtheworld.com, 2026-07-04","si_tag":"planning"},{"q":"When is the best time to visit Sian Ka''an?","a":"November–April, the dry season, is best — Dec–April brings optimal weather and the best wildlife viewing. Whatever the season, morning tours are calmer with fewer bugs; the May–October wet season is lush and quieter but brings afternoon storms and hurricane overlap (Jun–Nov). Because seats are capped, book earliest for the Dec–April and holiday windows.","source":"machupicchu.org / lifeontheroam.com, 2026-07-04","si_tag":"planning"}],"seo":{"meta_title":"Sian Ka''an Biosphere Reserve: UNESCO Wetlands Tour","meta_description":"Sian Ka''an - UNESCO biosphere south of Tulum: float 1,200-year-old Maya canals, birds and mangroves. Guided-only, remote; how and when to go.","slug":"sian-kaan-mexico","primary_keyword":"Sian Ka''an Biosphere Reserve","long_tail":["Sian Ka''an Muyil canal tour","Sian Ka''an from Tulum","Sian Ka''an boat tour","Sian Ka''an birding","Punta Allen Sian Ka''an"],"search_language":"bilingual (en + es-MX)","local_keywords":["Reserva de la Biosfera Sian Ka''an","Sian Ka''an desde Tulum","canales mayas Muyil","tour Muyil Sian Ka''an","Sian Ka''an que hacer","avistamiento de aves Sian Ka''an","Punta Allen Sian Ka''an"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-04","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-04","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]}},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"wildlife","status":"future"},{"si":"tropical","status":"future"}],"ultra":[],"source_verified":"2026-07-04","hero":{"query":"Sian Ka''an Biosphere Reserve, Mexico"},"geo":{"lat":19.5333,"lng":-87.6167},"orbit":[{"id":"akumal-mexico","jewels":5,"si":["diveglobal","ocean","culture"]},{"id":"bacalar-mexico","jewels":6,"si":["tropical","wellness","adventure"]},{"id":"cancun-mexico","jewels":5,"si":["tropical","adventure","diveglobal","ocean"]},{"id":"coba-mexico","jewels":5,"si":["culture","expedition","family"]},{"id":"cozumel-mexico","jewels":5,"si":["diveglobal","liveaboard","ocean"]},{"id":"holbox-mexico","jewels":4,"si":["expedition","romance","ocean","wildlife"]},{"id":"isla-contoy-mexico","jewels":3,"